package com.company.mobilebackend.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.ArrayList; import java.util.List;
@Entity @Table(name="orders",indexes={@Index(name="idx_orders_user_id",columnList="user_id"),@Index(name="idx_orders_status",columnList="status")}) public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id",nullable=false) private Long userId; @Enumerated(EnumType.STRING) @Column(nullable=false) private OrderStatus status; @Column(nullable=false) private BigDecimal totalAmount; @Column(updatable=false) private LocalDateTime createdAt; @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.LAZY) private List<OrderItem> orderItems=new ArrayList<>(); public Order(){} public Order(Long userId,OrderStatus status,BigDecimal totalAmount){this.userId=userId;this.status=status;this.totalAmount=totalAmount;} @PrePersist protected void onCreate(){createdAt=LocalDateTime.now();} public void addOrderItem(OrderItem i){orderItems.add(i);i.setOrder(this);} public Long getId(){return id;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public OrderStatus getStatus(){return status;} public void setStatus(OrderStatus v){status=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public LocalDateTime getCreatedAt(){return createdAt;} public List<OrderItem> getOrderItems(){return orderItems;} }
